def f(inp):
    H,W=len(inp),len(inp[0])
    # template component: 8-connected nonzero cells containing a 5 with nonzero neighbors
    nb=lambda r,c:[(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0) and 0<=r+dr<H and 0<=c+dc<W]
    seeds=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==5 and any(inp[x][y]!=0 for x,y in nb(r,c))]
    comp=set(); q=list(seeds); comp.update(seeds)
    while q:
        r,c=q.pop()
        for x,y in nb(r,c):
            if inp[x][y]!=0 and (x,y) not in comp: comp.add((x,y)); q.append((x,y))
    anchors=[p for p in comp if inp[p[0]][p[1]]==5 and len(nb(p[0],p[1]))>0]
    anchors=[anchors[0]]
    marks=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==5 and all(not(0<=r+dr<H and 0<=c+dc<W and inp[r+dr][c+dc]!=0) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0))]
    out=[row[:] for row in inp]
    for mr,mc in marks:
        sy,sx=mr-anchors[0][0],mc-anchors[0][1]
        for r,c in comp:
            nr,nc=r+sy,c+sx
            if 0<=nr<H and 0<=nc<W:
                out[nr][nc]=0 if inp[r][c]==5 else inp[r][c]
